  +'.tn-list{padding:6px 18px 0}.tn-card{position:relative;display:flex;align-items:center;gap:14px;min-height:112px;margin:0 0 14px;padding:16px 10px 16px 20px;border-radius:26px;background:var(--tn-bg);box-shadow:0 7px 16px rgba(170,140,115,.13),inset 0 1px 0 rgba(255,255,255,.7)}.tn-check{flex:0 0 auto;width:36px;height:36px;border-radius:50%;border:2.2px solid #cbb8b3;background:rgba(255,255,255,.45);padding:0;display:flex;align-items:center;justify-content:center}'
  +'.tn-main{flex:1;min-width:0}.tn-text{font-size:19px;font-weight:800;color:#3a332d;line-height:1.35;word-break:break-word}.tn-chip{display:inline-flex;align-items:center;gap:6px;margin-top:9px;padding:4px 12px 4px 9px;border-radius:14px;background:var(--tn-chip);font-size:14px;color:#5d5249}.tn-hint{display:block;margin-top:6px;font-size:11px;color:#a08f82}.tn-chip.late{background:#fbd9d5;color:#c4625d}.tn-text.long{font-size:16.5px;line-height:1.45;display:-webkit-box;-webkit-line-clamp:2;-webkit-box-orient:vertical;overflow:hidden}.tn-more{display:inline-block;margin-left:8px;font-size:12.5px;color:#b07a78;vertical-align:middle}.tn-card.pop .tn-check{animation:tnPop .45s ease}@keyframes tnPop{0%{transform:scale(1)}40%{transform:scale(1.28)}100%{transform:scale(1)}}.tn-star{position:absolute;left:30px;top:16px;z-index:3;color:#f2b33d;font-size:17px;font-weight:800;text-shadow:0 1px 0 #fff;pointer-events:none;animation:tnStar 1.1s ease-out forwards}@keyframes tnStar{0%{opacity:0;transform:translateY(8px) scale(.7)}20%{opacity:1;transform:translateY(0) scale(1.1)}100%{opacity:0;transform:translateY(-42px) scale(1)}}.tn-art{flex:0 0 auto;width:108px;height:88px;object-fit:contain;filter:drop-shadow(0 3px 4px rgba(150,115,90,.12))}'
